"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5744"],{3915(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>h,frontMatter:()=>a,contentTitle:()=>r,toc:()=>l,assets:()=>c});var o=JSON.parse('{"id":"how-to/cloud/kinesis_howto","title":"How to use the Kinesis Connector","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/cloud/kinesis_howto.md","sourceDirName":"how-to/cloud","slug":"/how-to/cloud/kinesis_howto","permalink":"/personal-av-docs/docs/how-to/cloud/kinesis_howto","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/cloud/kinesis_howto.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to use the Kinesis Connector","sidebar_label":"How to use the Kinesis Connector","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/howto/cloud/kinesis_howto","format":"md"}}'),i=t(4848),s=t(8453);let a={title:"How to use the Kinesis Connector",sidebar_label:"How to use the Kinesis Connector",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/howto/cloud/kinesis_howto",format:"md"},r="aws iam create-role --role-name sierra --assume-role-policy-document file:///.../Role-Trust-Policy.json",c={},l=[];function u(e){let n={a:"a",h1:"h1",header:"header",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(n.p,{children:[":::note Edition\n",(0,i.jsx)(n.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(n.a,{href:"https://doc.airvantage.net/connectivity/howto/cloud/kinesis_howto",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(n.p,{children:'How to use the Kinesis Connector\nIntegrate and extend your AirVantage platform\nHere we give you an overview of what you can do with the AirVantage Cloud Connector via a simple use case: Connecting your system to\nAWS Kinesis\nand getting raw data from your Kinesis stream.\nWe\u2019ll explain all the technical aspects needed for a robust, secure & reliable interface:\nprinciples & best practices\nconfiguration & authentication\nhow to get messages\n1 /\nPrinciples\n2 /\nConfiguration\n3 /\nGet messages\nPrinciples\nThis section explains when and why to use the Cloud connector, what it is and the available options.\nIntroduction\nThe Kinesis Cloud Connector provides:\nmessage notifications from AirVantage\nRobust messaging for applications\nHigh volume messaging\nRuns on all major operating systems\nOpen source libraries for several common languages (java, c#, python, PHP, \u2026)\nParameters\nWhen you connect AirVantage to Kinesis Streams, you have to define the type of notifications you want: operations, data, alert or usages.\nBe aware that Kinesis acknowledges a set of messages and not all individual messages.\nConfiguration\nThis section explains how to configure your client to be robust, reliable and secure. Please read carefully this section in order to supply correct information to enable the end point on the AirVantage side.\nWhat can I use?\nAWS SDK\nfor Java or\nKCL\nto start developing your application in your favorite language.\nAWS SDK is usefull to get started with Amazon Kinesis Streams, but you have to use KCL to build a complete application that can connect to Kinesis and process received data.\nPrerequisites\nSet up an Amazon web services account\nhere\n.\nIntroduction\nThe role describes the rights (called policies) allowed for an AWS account on a specific object (here a Kinesis sream).\nIn the schema on the right, we created an airvantageKinesisProducer role applied to AirVantage AWS account for a given company defined by the company uid in the secretKey.\nAllowed policies are the ones allowing to push messages in the stream and the last parameter defines the Kinesis Stream to use.\nConfiguration Process\nStep 1.\nCreate\na Kinesis stream in the customer\u2019s AWS account, into which AirVantage will publish.\nBe carefull ! There is a charge for using Kinesis streams resources. So before creating your stream, calculate the number of shards you need according to the quantity of data you handle and\nestimate\nyour corresponding bill.\nStep 2.\nCreate\na Role in the customer\u2019s AWS account:\nThe Role Type should be Cross-Account Access > 3rd party AWS account.\nThe Account ID should be 406826153012 (Sierra\u2019s own AWS account ID).\nThe External ID should be the UID of the customer\u2019s company in AirVantage.\nIn the role policy, click on Next and then Finish\nEdit the role in order to add an\nInline policies\n: The role\u2019s Policy should only allow Sierra to write into the Kinesis stream (kinesis:PutRecord, kinesis:PutRecords).\nIn case of you are not aware how to do this last step using the AWS Console, please have a look to\nHow to configure my stream?\nHow to configure my stream?\nHere is a detailed howto using\nAWS CLI\n:\nEdit the following Role-Trust-Policy.json replace\nby the AirVantage\u2019s company id of the company which we want to receive data from. In case of multiple AirVantag\u2019s companies, multiple roles and CloudConnector configuration must be created.\n{\n"Version": "2012-10-17",\n"Statement": [\n{\n"Action": "sts:AssumeRole",\n"Effect": "Allow",\n"Condition": { "StringEquals": { "sts:ExternalId": "<AIRVANTAGE COMPANY ID>" } },\n"Principal": { "AWS": "arn:aws:iam::406826153012:root" }\n}\n]\n}\nand execute:'}),"\n",(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"aws-iam-create-role---role-name-sierra---assume-role-policy-document-filerole-trust-policyjson",children:"aws iam create-role --role-name sierra --assume-role-policy-document file:///.../Role-Trust-Policy.json"})}),"\n",(0,i.jsx)(n.p,{children:'AWS response should look like :\n{\n"Role": {\n"AssumeRolePolicyDocument": {\n"Version": "2012-10-17",\n"Statement": [\n{\n"Action": "sts:AssumeRole",\n"Effect": "Allow",\n"Condition": {\n"StringEquals": {\n"sts:ExternalId": "<AIRVANTAGE COMPANY ID>"\n}\n},\n"Principal": {\n"AWS": "arn:aws:iam::406826153012:root"\n}\n}\n]\n},\n"RoleId": "<ROLE ID>",\n"CreateDate": "2016-09-12T12:16:16.727Z",\n"RoleName": "sierra",\n"Path": "/",\n"Arn": "arn:aws:iam::<AWS ACCOUNT ID>:role/sierra"\n}\n}\nThen edit the following Role-Policy.json and replace\nwith your AWS account id and\nwith the Kinesis stream delivery name.\n{\n"Version": "2012-10-17",\n"Statement": [\n{\n"Action": [\n"kinesis:PutRecord",\n"kinesis:PutRecords"\n],\n"Resource": [\n"arn:aws:kinesis:eu-west-1:<AWS ACCOUNT ID>:stream/<STREAM NAME>"\n],\n"Effect": "Allow"\n}\n]\n}\nand execute:'}),"\n",(0,i.jsx)(n.h1,{id:"aws-iam-put-role-policy---role-name-sierra---policy-name-kinesis_push---policy-document-filerole-policyjson",children:"aws iam put-role-policy --role-name sierra --policy-name kinesis_push --policy-document file:///.../Role-Policy.json"}),"\n",(0,i.jsx)(n.p,{children:"No response is expected from this command.\nNote:\nduring the creation of a Kinesis delivery stream with the AWS console an IAM role named\nkinesis_delivery_role\nis created. This role should not be added a Trusted relationship with AirVantage.\nStep 3.\nSupply the following information using the\nCRM\nand select\nRequest Support\n:\nCustomer\u2019s AWS Account ID (a 12-digit number).\nName of the Role they created for us.\nCustomer\u2019s AWS Region ID (e.g. us-east-1).\nName of the Kinesis stream we should write into.\nKind of messages you want to receive:\nAlert event: any alert rule triggered will be send\nOperation: any operation state will be sent (creation, progress, success or failed)\nNew message sent by the device: any device incoming communication\nUsages: any SIM usage\nNew message sent by the device: any device incoming communication\nOptionnaly you can supply the data path to whitelist the data (only the values for these data will be sent in the data stream). To get the data path for a data, you can go to the timeline to view the data path in the tooltip like in the screenshot below:\nTest your setup\nYou can check that the data received from AirVantage shows up in the stream monitoring provided by Amazon. The graph that describes the number of Put Record Requests lets you ensure that your Kinesis stream is connected to AirVantage. If no data is shown, you need to check your configuration.\nGet the messages\nThis section explains how to consume the messages from AWS Kinesis in order to support high volume messaging.\nUsing Kinesis Client Library\nKinesisStreamApp\n: This Kinesis stream java application  uses KCL to connect to Kinesis Streams and  pulls messages.\nInstallation\nConfigure\nthe AWS CLI:\naws configure\nis the command to type at the command line. It is an interactive command, you need to provide the following four pieces of information: AWS Access Key ID, AWS Secret Access Key, Default region, and Default output format.\naws configure\nClone the application using git from the repository.\nYou can optionally use eclipse to edit the files as an Eclipse project is supplied.\nThe source project is organized with three main files:\nA configuration file to edit (see next section)\nA Record Processor that processes records\nThe main application. This connects to the stream by creating a worker that pulls records, makes checkpoints and displays data on the console.\nConfiguration\nIn the configuration file\nconfig.properties\n, you have to specify:\nUnique Application name (a DynamoDB table is created for each application to save its state, such as checkpoints).\nNumber of records to receive to make a checkpoint\nMaximum number of records returned by one call\nStream name\nRegion (for instance\nus-west-2\n)\nHow to run\nThe configuration file\nconfig.properties\nhas to be adapted.\nEnjoy !\nTest\nCheck that the application displays the messages in the console. In the CloudWatch\nStream Monitoring, the Get Requests graph describes the evolution of Get Requests over time. And this shows that your application is successfully  connected to Kinesis and is retrieving messages.\nSamples\nKinesisStreamApp\nOther languages\n: You can find clients in various languages supplied by\nkinesis"})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>r});var o=t(6540);let i={},s=o.createContext(i);function a(e){let n=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:n},e.children)}}}]);